insert into te_passages (id, title, body, source, grade_level, difficulty, org_id) values
  ('c0000001-0000-0000-0000-000000000001', 'Why Expertise Can Become a Cage', 'The deeper a specialist goes into one field, the harder it becomes to see the field from outside. Expertise pays a quiet price.', 'thinking-english seed', 12, 'high', null),
  ('c0000002-0000-0000-0000-000000000002', 'The Quiet Tyranny of the Default', 'When a form arrives already filled in, most people simply sign it. The choices set in advance shape decisions far more than the choices people actively make.', 'thinking-english seed', 12, 'high', null),
  ('c0000003-0000-0000-0000-000000000003', 'When Numbers Lie by Telling the Truth', 'A statistic can be technically correct and still mislead the reader. The trick is not in the numbers but in what surrounds them.', 'thinking-english seed', 11, 'high', null),
  ('c0000004-0000-0000-0000-000000000004', 'The Cost of Constant Connection', 'A smartphone in the pocket changes attention even when it stays silent. The mind reserves a small piece of itself for the device that might call.', 'thinking-english seed', 12, 'high', null),
  ('c0000005-0000-0000-0000-000000000005', 'How Maps Quietly Argue', 'A map shows the world, but it also tells a story about the world. Where the center is placed, which borders are drawn boldly — these are choices, not facts.', 'thinking-english seed', 12, 'high', null),
  ('c0000006-0000-0000-0000-000000000006', 'The Limits of Imitation', 'Copying a master''s technique is the first step in learning, but it can become the last step too. The student who only imitates eventually stops growing.', 'thinking-english seed', 11, 'high', null),
  ('c0000007-0000-0000-0000-000000000007', 'Why Forgetting Helps Thinking', 'A brain that remembered everything could not function. Useful thinking depends on letting most details fall away so that the few important ones rise to the surface.', 'thinking-english seed', 12, 'high', null),
  ('c0000008-0000-0000-0000-000000000008', 'The Hidden Politics of Search', 'Two people typing the same words into a search bar can receive different results. The page that looks neutral has been quietly shaped before the search began.', 'thinking-english seed', 12, 'high', null),
  ('c0000009-0000-0000-0000-000000000009', 'The Long Tail of an Apology', 'A genuine apology does not erase the wound, but it does change the story attached to it. The same event remembered with a sincere apology is carried differently for years.', 'thinking-english seed', 11, 'high', null),
  ('c000000a-0000-0000-0000-00000000000a', 'Why Cities Outlive Empires', 'The empire that built a city often disappears, while the city goes on. Buildings and roads keep working long after the rulers who funded them are forgotten.', 'thinking-english seed', 12, 'high', null),
  ('c000000b-0000-0000-0000-00000000000b', 'The Paradox of Choice in Markets', 'A market with hundreds of brands seems free, but the abundance itself can paralyze the buyer. Freedom of choice and ease of choice are not the same thing.', 'thinking-english seed', 12, 'high', null),
  ('c000000c-0000-0000-0000-00000000000c', 'When Help Hurts', 'Generous aid sent to a struggling region can quietly destroy the local industries that used to serve the same need. The intention does not match the outcome.', 'thinking-english seed', 12, 'high', null),
  ('c000000d-0000-0000-0000-00000000000d', 'The Long Sentence That Says Nothing', 'A sentence built of many large words sometimes sounds wise but conveys very little. Difficulty of style is not the same as depth of thought.', 'thinking-english seed', 11, 'high', null),
  ('c000000e-0000-0000-0000-00000000000e', 'Why Innovation Often Comes From Outsiders', 'The people who change a field most are often newcomers who have not yet learned what cannot be done. Inexperience can act as a kind of permission.', 'thinking-english seed', 12, 'high', null),
  ('c000000f-0000-0000-0000-00000000000f', 'The Discipline of Slowness', 'In an era that rewards speed, choosing to slow down feels almost rebellious. Yet many decisions made quickly carry costs that show up only later.', 'thinking-english seed', 12, 'high', null);

-- ===== 단락 ===========================================================
insert into te_paragraphs (passage_id, ord, body) values
  ('c0000001-0000-0000-0000-000000000001', 0, 'An expert learns to see patterns most people miss. The same training, however, builds blind spots in the places where the expert no longer looks because the answer feels obvious.'),
  ('c0000001-0000-0000-0000-000000000001', 1, 'Outsiders sometimes solve problems that have stumped specialists for years. They lack the assumptions that quietly closed certain doors inside the field.'),
  ('c0000001-0000-0000-0000-000000000001', 2, 'The lesson is not to avoid expertise but to balance it. A specialist who keeps one foot outside her own field sees both the inside and the door at the same time.'),

  ('c0000002-0000-0000-0000-000000000002', 0, 'When organ donation is opt-out instead of opt-in, registration rates jump dramatically. The same population, the same beliefs, but a different default produces a different result.'),
  ('c0000002-0000-0000-0000-000000000002', 1, 'Defaults work because changing them takes a small but real effort, and most people do not pay that cost. The choice that requires no action wins, regardless of what people would have decided in the abstract.'),
  ('c0000002-0000-0000-0000-000000000002', 2, 'Whoever sets the default holds quiet power. This is why the design of forms, menus, and settings is never neutral, even when it looks technical.'),

  ('c0000003-0000-0000-0000-000000000003', 0, 'A report says crime has dropped by fifty percent. The number is true, but the period chosen runs from an unusual spike to an ordinary year. The trend looks dramatic only because of where the line begins.'),
  ('c0000003-0000-0000-0000-000000000003', 1, 'Averages also hide as much as they show. The average income in a room can rise sharply if one billionaire walks in, even though everyone else earned nothing new.'),
  ('c0000003-0000-0000-0000-000000000003', 2, 'A careful reader asks not what the number is but how it was made. The framing of a statistic often decides its meaning before the digits ever appear.'),

  ('c0000004-0000-0000-0000-000000000004', 0, 'Studies show that simply having a smartphone on the table during a conversation reduces how connected the participants feel, even when the phone never lights up.'),
  ('c0000004-0000-0000-0000-000000000004', 1, 'The brain treats the possibility of an alert like a low background hum. A part of attention stays ready for the device, which leaves less attention for the people in the room.'),
  ('c0000004-0000-0000-0000-000000000004', 2, 'The fix is not to throw away the phone but to recognize the cost. Putting the device out of sight for a defined period changes the depth of the conversation that follows.'),

  ('c0000005-0000-0000-0000-000000000005', 0, 'A flat map of the round earth is always a compromise. Some maps preserve area; others preserve direction; none can do both. The choice of projection quietly decides which countries look large or small.'),
  ('c0000005-0000-0000-0000-000000000005', 1, 'Borders, too, are often drawn cleanly on the page where the ground itself is messy. A river that shifts each year becomes a single fixed line in the atlas.'),
  ('c0000005-0000-0000-0000-000000000005', 2, 'A reader who notices these choices begins to read maps the way a critic reads paintings. The image is not the world; it is one argument about the world.'),

  ('c0000006-0000-0000-0000-000000000006', 0, 'Beginning students copy a master to absorb how each line is made. The hand learns through the muscles what the eyes have only seen so far.'),
  ('c0000006-0000-0000-0000-000000000006', 1, 'At a certain point, however, the imitation becomes a ceiling. The student who never risks her own line repeats the master''s strengths but also his limits.'),
  ('c0000006-0000-0000-0000-000000000006', 2, 'Real growth begins when the imitator misses on purpose, leaving in the mistakes that turn out to be a voice. The same path that started in copying ends in something new.'),

  ('c0000007-0000-0000-0000-000000000007', 0, 'Forgetting is often described as failure, but it is also a quiet form of editing. Without it, every old phone number, address, and trivial conversation would crowd the mind permanently.'),
  ('c0000007-0000-0000-0000-000000000007', 1, 'Studies of people who cannot forget show that their lives are filled with intrusive detail rather than richer thought. Memory weighed down by everything has no room to compare or generalize.'),
  ('c0000007-0000-0000-0000-000000000007', 2, 'Good thinking, then, is less like collecting and more like sculpting. The form emerges from what has been removed, not only from what remains.'),

  ('c0000008-0000-0000-0000-000000000008', 0, 'Search engines do not present a fixed list of pages. They predict which pages are most useful to each individual, based on past behavior, location, and many signals invisible to the user.'),
  ('c0000008-0000-0000-0000-000000000008', 1, 'This personalization can be convenient, but it also means two readers cannot fully share what they have seen. Public debate becomes harder when each citizen reads from a slightly different page.'),
  ('c0000008-0000-0000-0000-000000000008', 2, 'A neutral-looking search bar carries decisions made elsewhere. Knowing this does not change the results, but it changes the trust the reader places in them.'),

  ('c0000009-0000-0000-0000-000000000009', 0, 'When a wrong is followed by silence, the memory of it stays sharp. The person harmed keeps repeating the event in private, trying to make sense of what happened.'),
  ('c0000009-0000-0000-0000-000000000009', 1, 'A real apology does not undo the act. It does, however, give the event an ending. The story can now include the words that closed it, not only the moment that opened it.'),
  ('c0000009-0000-0000-0000-000000000009', 2, 'This is why the timing of an apology matters as much as its content. A late apology repairs less because by then the story has hardened into its private form.'),

  ('c000000a-0000-0000-0000-00000000000a', 0, 'Rome fell, but Rome the city continued. Babylon, Constantinople, and many ancient capitals outlasted the powers that founded them. Infrastructure has a longer memory than rulers.'),
  ('c000000a-0000-0000-0000-00000000000a', 1, 'Roads, harbors, and walls keep doing useful work long after their original purpose ends. New generations route their lives along old stones without noticing whose feet first wore them down.'),
  ('c000000a-0000-0000-0000-00000000000a', 2, 'A city is therefore a kind of fossil and a living organism at the same time. It carries decisions that nobody alive made, and it shapes decisions that nobody dead can predict.'),

  ('c000000b-0000-0000-0000-00000000000b', 0, 'Classical economics assumes that more options serve the buyer. In practice, when the number of options grows large, decisions become slower, regrets stronger, and satisfaction lower.'),
  ('c000000b-0000-0000-0000-00000000000b', 1, 'The buyer carries an invisible burden. Every choice opens new questions: Could one of the other options have been better? The chosen option must now defend itself against forty unseen rivals.'),
  ('c000000b-0000-0000-0000-00000000000b', 2, 'Well-designed markets curate choice rather than maximize it. A shorter list, chosen with care, often produces buyers who feel both freer and happier than a longer list ever could.'),

  ('c000000c-0000-0000-0000-00000000000c', 0, 'A donation of free shoes to a struggling area sounds harmless. Yet local shoemakers, who survive on small margins, suddenly lose their customers. The visiting gift quietly closes the local door.'),
  ('c000000c-0000-0000-0000-00000000000c', 1, 'Cash transfers to the same households often produce better outcomes. Recipients spend on locally made goods, which strengthens neighboring producers instead of replacing them.'),
  ('c000000c-0000-0000-0000-00000000000c', 2, 'The lesson is that good intentions cannot stand alone. Aid that ignores the local economy can erase what it was meant to support.'),

  ('c000000d-0000-0000-0000-00000000000d', 0, 'Some writers hide thin ideas behind dense language. A sentence packed with abstract nouns and rare adjectives can feel important even when, examined closely, it says almost nothing.'),
  ('c000000d-0000-0000-0000-00000000000d', 1, 'Reading slowly reveals the trick. When a passage resists every attempt at simple paraphrase, the resistance often points to absence rather than depth.'),
  ('c000000d-0000-0000-0000-00000000000d', 2, 'Clear writing is harder than complex writing. A short sentence that survives translation into a child''s words has earned the right to look simple.'),

  ('c000000e-0000-0000-0000-00000000000e', 0, 'Newcomers ask questions that insiders have stopped asking, because insiders have already learned which questions sound foolish. The foolish question is sometimes the one that breaks the field open.'),
  ('c000000e-0000-0000-0000-00000000000e', 1, 'Many famous inventions appeared at the edges where two fields touched, brought there by people who belonged fully to neither. They could carry a tool from one world into another without seeing the imagined wall between them.'),
  ('c000000e-0000-0000-0000-00000000000e', 2, 'This does not mean every outsider becomes an innovator. It means an outsider has a chance the insider has slowly traded away.'),

  ('c000000f-0000-0000-0000-00000000000f', 0, 'A culture that prizes speed treats slowness as weakness. Quick decisions are praised; long pauses are suspected of indecision. But the metric is not always honest about what was decided.'),
  ('c000000f-0000-0000-0000-00000000000f', 1, 'A choice made in three seconds and a choice made in three days do not always reach the same place. Some problems reveal their shape only after we stop pushing on them.'),
  ('c000000f-0000-0000-0000-00000000000f', 2, 'Choosing slowness is not laziness. It is a disciplined refusal to confuse the appearance of progress with the substance of it.');

-- ===== 문제 (지문당 3개: 주제 1 + 빈칸 1 + 어휘 1) =====================
insert into te_questions (passage_id, topic, prompt, choices, correct_answer, explanation, difficulty, grade_level, org_id) values
  ('c0000001-0000-0000-0000-000000000001', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Expertise has no costs."},{"key":"2","text":"Deep expertise creates blind spots, so specialists benefit from staying connected to outside perspectives."},{"key":"3","text":"Outsiders can never solve specialist problems."},{"key":"4","text":"Specialists should never balance their knowledge."}]',
   '2', '본문 결론: 전문성은 가치 있지만 외부 시각과 균형 필요.', 'high', 12, null),
  ('c0000001-0000-0000-0000-000000000001', 'blank', 'Fill in the blank: A specialist who keeps one foot ____ her own field sees both the inside and the door at the same time.',
   '[{"key":"1","text":"inside"},{"key":"2","text":"under"},{"key":"3","text":"outside"},{"key":"4","text":"behind"}]',
   '3', 'one foot outside her own field.', 'high', 12, null),
  ('c0000001-0000-0000-0000-000000000001', 'vocabulary', 'In the passage, "stumped" most nearly means:',
   '[{"key":"1","text":"made unable to find an answer"},{"key":"2","text":"made very happy"},{"key":"3","text":"prepared in advance"},{"key":"4","text":"forgotten quickly"}]',
   '1', '문제로 stumped specialists → 막혀 있던.', 'high', 12, null),

  ('c0000002-0000-0000-0000-000000000002', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Defaults are neutral and harmless."},{"key":"2","text":"Defaults quietly steer many decisions, and whoever sets them holds power."},{"key":"3","text":"Forms should always be blank."},{"key":"4","text":"Organ donation is a personal matter only."}]',
   '2', '전체 단락 흐름과 결론: 기본값 설계자가 결정에 큰 힘.', 'high', 12, null),
  ('c0000002-0000-0000-0000-000000000002', 'blank', 'Fill in the blank: The choice that requires no action ____, regardless of what people would have decided in the abstract.',
   '[{"key":"1","text":"fails"},{"key":"2","text":"wins"},{"key":"3","text":"hides"},{"key":"4","text":"complains"}]',
   '2', 'requires no action wins.', 'high', 12, null),
  ('c0000002-0000-0000-0000-000000000002', 'vocabulary', 'In the passage, "in the abstract" most nearly means:',
   '[{"key":"1","text":"in actual practice"},{"key":"2","text":"in theory, apart from real situations"},{"key":"3","text":"in a painting"},{"key":"4","text":"in a strong sense"}]',
   '2', 'in the abstract → 추상적으로, 실제 상황과 별개로.', 'high', 12, null),

  ('c0000003-0000-0000-0000-000000000003', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Statistics are always wrong."},{"key":"2","text":"A statistic can be technically true yet misleading; framing decides its meaning."},{"key":"3","text":"Averages reveal everything important."},{"key":"4","text":"Readers should avoid all numbers."}]',
   '2', '본문 결론: 통계의 framing이 진짜 의미를 결정.', 'high', 11, null),
  ('c0000003-0000-0000-0000-000000000003', 'blank', 'Fill in the blank: The average income in a room can rise sharply if one ____ walks in.',
   '[{"key":"1","text":"child"},{"key":"2","text":"billionaire"},{"key":"3","text":"reader"},{"key":"4","text":"teacher"}]',
   '2', 'one billionaire walks in.', 'high', 11, null),
  ('c0000003-0000-0000-0000-000000000003', 'vocabulary', 'In the passage, "framing" most nearly means:',
   '[{"key":"1","text":"the way information is presented"},{"key":"2","text":"a picture border"},{"key":"3","text":"a math equation"},{"key":"4","text":"a kind of glass"}]',
   '1', '비유 표현이지만 맥락은 정보 제시 방식.', 'high', 11, null),

  ('c0000004-0000-0000-0000-000000000004', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Phones must be destroyed."},{"key":"2","text":"Even a silent phone steals part of our attention; intentional separation helps."},{"key":"3","text":"Conversations are not affected by devices."},{"key":"4","text":"Alerts are the only problem."}]',
   '2', '본문 결론: 잠재적 알림이 주의를 분산. 의도적으로 떼어놓기.', 'high', 12, null),
  ('c0000004-0000-0000-0000-000000000004', 'blank', 'Fill in the blank: The brain treats the possibility of an alert like a low background ____.',
   '[{"key":"1","text":"hum"},{"key":"2","text":"river"},{"key":"3","text":"flower"},{"key":"4","text":"flame"}]',
   '1', 'a low background hum.', 'high', 12, null),
  ('c0000004-0000-0000-0000-000000000004', 'vocabulary', 'In the passage, "reserves" most nearly means:',
   '[{"key":"1","text":"sets aside or keeps for a purpose"},{"key":"2","text":"throws out"},{"key":"3","text":"forgets"},{"key":"4","text":"shouts loudly"}]',
   '1', 'reserves a small piece of itself → 일부를 따로 떼어둔다.', 'high', 12, null),

  ('c0000005-0000-0000-0000-000000000005', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Maps are objective records of the world."},{"key":"2","text":"Maps embed choices that quietly shape how we see the world."},{"key":"3","text":"Borders are always perfectly drawn."},{"key":"4","text":"Round maps are impossible."}]',
   '2', '전체 단락이 지도의 선택성과 주장성 강조.', 'high', 12, null),
  ('c0000005-0000-0000-0000-000000000005', 'blank', 'Fill in the blank: The image is not the world; it is one ____ about the world.',
   '[{"key":"1","text":"painting"},{"key":"2","text":"argument"},{"key":"3","text":"city"},{"key":"4","text":"forest"}]',
   '2', 'one argument about the world.', 'high', 12, null),
  ('c0000005-0000-0000-0000-000000000005', 'vocabulary', 'In the passage, "projection" most nearly means:',
   '[{"key":"1","text":"a method of representing a round surface on flat paper"},{"key":"2","text":"a movie shown on a wall"},{"key":"3","text":"a prediction about the future"},{"key":"4","text":"a long shadow"}]',
   '1', 'choice of projection → 투영법.', 'high', 12, null),

  ('c0000006-0000-0000-0000-000000000006', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Beginners should never imitate."},{"key":"2","text":"Imitation is a beginning, but growth requires moving beyond it into one''s own voice."},{"key":"3","text":"A master''s technique is the final goal."},{"key":"4","text":"Risking mistakes harms learning."}]',
   '2', '본문 결론: 모방으로 시작하지만 자기 표현으로 끝남.', 'high', 11, null),
  ('c0000006-0000-0000-0000-000000000006', 'blank', 'Fill in the blank: Real growth begins when the imitator misses on ____.',
   '[{"key":"1","text":"command"},{"key":"2","text":"accident"},{"key":"3","text":"purpose"},{"key":"4","text":"holiday"}]',
   '3', 'misses on purpose.', 'high', 11, null),
  ('c0000006-0000-0000-0000-000000000006', 'vocabulary', 'In the passage, "ceiling" most nearly means:',
   '[{"key":"1","text":"the top of a room"},{"key":"2","text":"an upper limit one cannot pass"},{"key":"3","text":"a kind of art"},{"key":"4","text":"a teacher"}]',
   '2', '비유: imitation이 ceiling이 된다 → 더 못 올라가는 한계.', 'high', 11, null),

  ('c0000007-0000-0000-0000-000000000007', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Forgetting is purely a failure of memory."},{"key":"2","text":"Forgetting is a necessary part of good thinking, like editing or sculpting."},{"key":"3","text":"People who remember everything think more clearly."},{"key":"4","text":"Memory should hold every detail."}]',
   '2', '본문 결론: 좋은 사고는 덜어내는 것에서 나온다.', 'high', 12, null),
  ('c0000007-0000-0000-0000-000000000007', 'blank', 'Fill in the blank: Good thinking is less like collecting and more like ____.',
   '[{"key":"1","text":"sculpting"},{"key":"2","text":"painting"},{"key":"3","text":"buying"},{"key":"4","text":"shouting"}]',
   '1', 'more like sculpting.', 'high', 12, null),
  ('c0000007-0000-0000-0000-000000000007', 'vocabulary', 'In the passage, "intrusive" most nearly means:',
   '[{"key":"1","text":"interrupting where not wanted"},{"key":"2","text":"forgettable"},{"key":"3","text":"polite and quiet"},{"key":"4","text":"helpful"}]',
   '1', 'intrusive detail → 침입하듯 떠오르는 세부.', 'high', 12, null),

  ('c0000008-0000-0000-0000-000000000008', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Search engines show everyone the same results."},{"key":"2","text":"Personalized search shapes what each user sees, making shared public knowledge harder."},{"key":"3","text":"Personalization is purely convenient with no costs."},{"key":"4","text":"Search bars are politically neutral."}]',
   '2', '전체 단락 흐름: 편의 + 공공 토론 약화.', 'high', 12, null),
  ('c0000008-0000-0000-0000-000000000008', 'blank', 'Fill in the blank: Public debate becomes harder when each citizen reads from a slightly different ____.',
   '[{"key":"1","text":"book"},{"key":"2","text":"page"},{"key":"3","text":"city"},{"key":"4","text":"clock"}]',
   '2', 'a slightly different page.', 'high', 12, null),
  ('c0000008-0000-0000-0000-000000000008', 'vocabulary', 'In the passage, "neutral-looking" most nearly means:',
   '[{"key":"1","text":"appearing fair and unbiased"},{"key":"2","text":"clearly biased"},{"key":"3","text":"deeply colored"},{"key":"4","text":"very loud"}]',
   '1', 'neutral-looking search bar → 중립처럼 보이는.', 'high', 12, null),

  ('c0000009-0000-0000-0000-000000000009', 'main_idea', 'What is the main idea?',
   '[{"key":"1","text":"Apologies are always too late to matter."},{"key":"2","text":"A timely, sincere apology cannot undo an act but it changes how the event is remembered."},{"key":"3","text":"Silence after harm has no consequence."},{"key":"4","text":"Apologies erase wounds completely."}]',
   '2', '본문 핵심: 사과의 의미와 시간성.', 'high', 11, null),
  ('c0000009-0000-0000-0000-000000000009', 'blank', 'Fill in the blank: A late apology repairs less because by then the story has ____ into its private form.',
   '[{"key":"1","text":"softened"},{"key":"2","text":"hardened"},{"key":"3","text":"shrunk"},{"key":"4","text":"sung"}]',
   '2', 'story has hardened.', 'high', 11, null),
  ('c0000009-0000-0000-0000-000000000009', 'vocabulary', 'In the passage, "intrusive" might be replaced; but "sincere" most nearly means:',
   '[{"key":"1","text":"honest and truly meant"},{"key":"2","text":"fake and rehearsed"},{"key":"3","text":"loud and quick"},{"key":"4","text":"private"}]',
   '1', 'sincere apology → 진심 어린.', 'high', 11, null),

  ('c000000a-0000-0000-0000-00000000000a', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Cities collapse with their empires."},{"key":"2","text":"Cities often outlast their founding powers, carrying invisible decisions across generations."},{"key":"3","text":"Old infrastructure is useless."},{"key":"4","text":"Empires last longer than buildings."}]',
   '2', '본문 결론: 인프라가 통치보다 오래 살아남는다.', 'high', 12, null),
  ('c000000a-0000-0000-0000-00000000000a', 'blank', 'Fill in the blank: New generations route their lives along old stones without noticing whose feet first ____ them down.',
   '[{"key":"1","text":"wore"},{"key":"2","text":"painted"},{"key":"3","text":"counted"},{"key":"4","text":"sang"}]',
   '1', 'first wore them down.', 'high', 12, null),
  ('c000000a-0000-0000-0000-00000000000a', 'vocabulary', 'In the passage, "fossil" most nearly means:',
   '[{"key":"1","text":"the preserved remains of something from a past age"},{"key":"2","text":"a kind of plant"},{"key":"3","text":"a new invention"},{"key":"4","text":"a small animal"}]',
   '1', '비유: 도시 = 화석이면서 살아있는 유기체.', 'high', 12, null),

  ('c000000b-0000-0000-0000-00000000000b', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"More options always mean happier buyers."},{"key":"2","text":"Beyond a point, more options reduce satisfaction; curated choice often serves buyers better."},{"key":"3","text":"Classical economics is always right about choice."},{"key":"4","text":"Markets should never limit options."}]',
   '2', '본문 핵심: 선택 과잉의 역설.', 'high', 12, null),
  ('c000000b-0000-0000-0000-00000000000b', 'blank', 'Fill in the blank: Well-designed markets ____ choice rather than maximize it.',
   '[{"key":"1","text":"curate"},{"key":"2","text":"erase"},{"key":"3","text":"sell"},{"key":"4","text":"copy"}]',
   '1', 'markets curate choice.', 'high', 12, null),
  ('c000000b-0000-0000-0000-00000000000b', 'vocabulary', 'In the passage, "paralyze" most nearly means:',
   '[{"key":"1","text":"to leave someone unable to act"},{"key":"2","text":"to reward generously"},{"key":"3","text":"to copy slowly"},{"key":"4","text":"to celebrate"}]',
   '1', 'abundance can paralyze the buyer → 의사결정 마비.', 'high', 12, null),

  ('c000000c-0000-0000-0000-00000000000c', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"All foreign aid is harmful."},{"key":"2","text":"Aid designed without regard for the local economy can damage the very community it intends to help."},{"key":"3","text":"Free shoes always help."},{"key":"4","text":"Cash transfers always fail."}]',
   '2', '본문 결론: 의도와 결과가 다르다.', 'high', 12, null),
  ('c000000c-0000-0000-0000-00000000000c', 'blank', 'Fill in the blank: Aid that ignores the local economy can ____ what it was meant to support.',
   '[{"key":"1","text":"strengthen"},{"key":"2","text":"erase"},{"key":"3","text":"repair"},{"key":"4","text":"sell"}]',
   '2', 'can erase what it was meant to support.', 'high', 12, null),
  ('c000000c-0000-0000-0000-00000000000c', 'vocabulary', 'In the passage, "margins" most nearly means:',
   '[{"key":"1","text":"edges of pages"},{"key":"2","text":"the small profit left after costs"},{"key":"3","text":"large profits"},{"key":"4","text":"empty rooms"}]',
   '2', 'survive on small margins → 적은 이윤.', 'high', 12, null),

  ('c000000d-0000-0000-0000-00000000000d', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Difficult writing is always deep."},{"key":"2","text":"Style complexity does not equal depth; clear writing often hides more thinking than dense writing does."},{"key":"3","text":"All long sentences are empty."},{"key":"4","text":"Simple writing is lazy."}]',
   '2', '본문 결론: 명료한 글이 더 어렵다.', 'high', 11, null),
  ('c000000d-0000-0000-0000-00000000000d', 'blank', 'Fill in the blank: A short sentence that survives translation into a child''s words has earned the right to look ____.',
   '[{"key":"1","text":"simple"},{"key":"2","text":"large"},{"key":"3","text":"hidden"},{"key":"4","text":"loud"}]',
   '1', 'earned the right to look simple.', 'high', 11, null),
  ('c000000d-0000-0000-0000-00000000000d', 'vocabulary', 'In the passage, "paraphrase" most nearly means:',
   '[{"key":"1","text":"to restate in different words"},{"key":"2","text":"to write a long poem"},{"key":"3","text":"to repeat exactly"},{"key":"4","text":"to forget completely"}]',
   '1', 'resists simple paraphrase → 다른 말로 풀어쓰기.', 'high', 11, null),

  ('c000000e-0000-0000-0000-00000000000e', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Only insiders can change a field."},{"key":"2","text":"Outsiders often bring innovation because they lack the assumptions insiders no longer question."},{"key":"3","text":"Foolish questions should be avoided."},{"key":"4","text":"Field boundaries are real walls."}]',
   '2', '본문 핵심: 외부인의 무지가 오히려 자유를 줌.', 'high', 12, null),
  ('c000000e-0000-0000-0000-00000000000e', 'blank', 'Fill in the blank: Inexperience can act as a kind of ____.',
   '[{"key":"1","text":"prison"},{"key":"2","text":"permission"},{"key":"3","text":"sleep"},{"key":"4","text":"alarm"}]',
   '2', 'a kind of permission.', 'high', 12, null),
  ('c000000e-0000-0000-0000-00000000000e', 'vocabulary', 'In the passage, "imagined wall" most nearly means:',
   '[{"key":"1","text":"a real physical barrier"},{"key":"2","text":"a boundary that exists mostly in people''s minds"},{"key":"3","text":"a kind of brick"},{"key":"4","text":"a tall mountain"}]',
   '2', '비유: imagined wall = 사람들이 마음속에 만든 경계.', 'high', 12, null),

  ('c000000f-0000-0000-0000-00000000000f', 'main_idea', 'What is the writer''s main point?',
   '[{"key":"1","text":"Quick decisions are always best."},{"key":"2","text":"Choosing to slow down is a disciplined act, not laziness, and often produces better decisions."},{"key":"3","text":"Slowness is weakness in any culture."},{"key":"4","text":"Speed equals depth."}]',
   '2', '본문 결론: slowness는 진짜 진보의 본질.', 'high', 12, null),
  ('c000000f-0000-0000-0000-00000000000f', 'blank', 'Fill in the blank: It is a disciplined refusal to confuse the appearance of progress with the ____ of it.',
   '[{"key":"1","text":"substance"},{"key":"2","text":"color"},{"key":"3","text":"sound"},{"key":"4","text":"smell"}]',
   '1', 'with the substance of it.', 'high', 12, null),
  ('c000000f-0000-0000-0000-00000000000f', 'vocabulary', 'In the passage, "rebellious" most nearly means:',
   '[{"key":"1","text":"going against what is expected"},{"key":"2","text":"silent and obedient"},{"key":"3","text":"warmly welcoming"},{"key":"4","text":"easily afraid"}]',
   '1', 'feels almost rebellious → 반항적으로 느껴진다.', 'high', 12, null);
